class Cache
  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  def write(key, payload, stale: false)
    data = pack(@packer, payload)
    @store[key] = { data: data, stale: !!stale }
  end

  def read(key)
    entry = @store[key]
    return nil unless entry
    unpack(@packer, entry[:data])
  end

  def sweep
    @store.delete_if { |_key, entry| entry[:stale] }
  end

  private

  def pack(packer, payload)
    packer ? packer.dump(payload) : payload
  end

  def unpack(packer, data)
    packer ? packer.load(data) : data
  end
end
